    centers=[(r,c,g[r][c]) for r in range(h) for c in range(len(g[r])) if g[r][c] not in (0,3)]
    original=[row[:] for row in g]
    # Each center projects its color along its row and column. It erases other colors,
    # while the original gray 3 markers remain visible.
    for r,c,col in centers:
        for x in range(w):
            if original[r][x] != 3:
                g[r][x]=col
        for y in range(h):
            if original[y][c] != 3:
                g[y][c]=col
    return g
