 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0])
    original=[row[:] for row in g]
    centers=[(r,c,original[r][c]) for r in range(h) for c in range(w) if original[r][c] not in (0,3)]
    # Colored centers project their colors along entire rows and columns; existing
    # gray marker cells remain untouched. Horizontal projections are drawn first,
    # then vertical projections, so vertical lines win at intersections.
    for r,c,color in centers:
        for x in range(w):
            if original[r][x] != 3:
                g[r][x]=color
    for r,c,color in centers:
        for y in range(h):
            if original[y][c] != 3:
                g[y][c]=color
    return g
